/* Static design study. No game imports, storage, editing, or motion.
   Three different Workshop layouts; ?variant=A|B|C, ?screen=edit|home|try. */
const q = new URLSearchParams(location.search);
const variant = ['A','B','C'].includes(q.get('variant')) ? q.get('variant') : 'A';
const screen = ['home','try'].includes(q.get('screen')) ? q.get('screen') : 'edit';
const asset = '../../../../public/';
const names = {A:'Board first',B:'Step by step',C:'Piece card'};
const fig = (piece='knight',cls='') => `<img class="piece ${cls}" alt="${piece}" src="${asset}ui/pieces/${piece}-w.webp">`;
const button = (text,cls='') => `<button type="button" class="${cls}" tabindex="-1">${text}</button>`;
const chevron = '<span aria-hidden="true">›</span>';
const status = '<span class="saved">✓ Saved on this device</span>';
const ruleText = 'After a take by moving, it may take again from the new square, but not a king.';
function board(n=7,trial=false) {
 let cells='';
 for(let y=0;y<n;y++)for(let x=0;x<n;x++){
  const dx=x-3,dy=y-(trial?4:3), center=dx===0&&dy===0;
  const mark=Math.abs(dx)*Math.abs(dy)===2;
  const enemy=trial&&((x===5&&y===3)||(x===3&&y===2)||(x===1&&y===3));
  cells+=`<div class="square ${(x+y)%2?'shade':''} ${center?'origin':''}">${center?fig():enemy?`<img class="enemy" alt="Enemy pawn" src="${asset}ui/pieces/pawn-b.webp">`:''}${mark?`<span class="move-dot ${enemy?'capture':''}">${enemy?'×':''}</span>`:''}</div>`;
 }
 return `<div class="board-wrap"><div class="orientation">FORWARD ↑</div><div class="board" style="--n:${n}" role="img" aria-label="${trial?'Trial board with the Hungry Rider and enemy pieces':'Seven by seven move board. A knight at the centre can move and take in eight L shapes.'}">${cells}</div><div class="legend"><span><i class="mini-dot"></i> Move or take</span><span>${trial?'Tap a marked square.':'Tap a square to add or remove it.'}</span></div></div>`;
}
const value = (full=false) => `<div class="value"><div><span class="eyebrow">ESTIMATED WORTH</span><strong>About 4½ <small>pawns</small></strong></div><span class="fair">Within range</span></div>${full?'<p class="value-note">About as strong as a Beast. This is an estimate.</p>':''}`;
const tabs = (active='Moves') => `<nav class="tabs" aria-label="Piece parts">${['Moves','Rules · 1','Look'].map(t=>button(t,t===active?'selected':'')).join('')}</nav>`;
const tools = () => `<div class="tools"><div><span class="eyebrow">ACTION</span>${button('Move + take ▾','tool')}</div><div><span class="eyebrow">APPLY TO</span>${button('All sides ▾','tool')}</div>${button('↶','undo')}</div>`;
const rule = () => `<div class="rule"><div class="row"><span class="eyebrow">RULE 1 OF 3</span>${button('Edit '+chevron,'text-button')}</div><strong>Takes again</strong><p>${ruleText}</p></div>`;
function header(label='Hungry Rider',step=''){return `<header><div class="crumb">${button('‹ <span>Workshop</span>','back')}<span class="divider"></span><span class="header-label">${label}</span></div>${step?`<span class="step-count">${step}</span>`:status}<div class="header-actions">${button('Share','share')}</div></header>`;}
function appA(){return `${header()}<div class="workbench"><section class="canvas"><div class="section-heading"><div><span class="eyebrow">YOUR PIECE</span><h1>Hungry Rider <span class="pencil">↗</span></h1></div><div class="mode">${button('Edit','selected')}${button('Try it')}</div></div><div class="mobile-value">About 4½ pawns <span>· Estimate</span><button class="text-button" tabindex="-1">Why?</button></div>${tabs()}${tools()}${board()}<div class="board-caption">Moves and takes in an L. It can jump over pieces.</div></section><aside class="inspector"><div class="identity">${fig()}<div><span class="eyebrow">BASED ON A KNIGHT</span><h2>Hungry Rider</h2><p>One special rule.</p></div></div>${value(true)}<div class="disclosure">${button('Why this estimate? '+chevron,'text-button')}</div>${rule()}${button('+ Add a rule','add')}<div class="look-row">${fig()}<div><strong>Ivory knight</strong><p>No glow · Letter H</p></div>${button('Look '+chevron,'text-button')}</div><p class="scope">Try and share your piece.<br>Custom pieces cannot join games yet.</p></aside></div><footer class="foot-a">${status}<span class="foot-note">Custom pieces cannot join games yet.</span>${button('Try it →','primary')}</footer>`;}
function appB(){return `${header('New piece','STEP 2 OF 4')}<div class="guided"><aside class="steps"><div class="guide-title"><span class="eyebrow">MAKE IT YOUR OWN</span><h1>A piece,<br>one choice<br>at a time.</h1></div><ol><li class="complete"><i>✓</i><div>Start<span>Knight</span></div></li><li class="active"><i>2</i><div>Moves<span>Choose its squares</span></div></li><li><i>3</i><div>Rules<span>Add up to three</span></div></li><li><i>4</i><div>Look & name<span>Make it yours</span></div></li></ol><div class="step-art">${fig()}<span>Hungry Rider</span></div></aside><section class="step-body"><div class="mobile-steps"><span>✓ Start</span><b>2 Moves</b><span>3 Rules</span><span>4 Look</span></div><div class="step-intro"><span class="eyebrow">STEP 2 · MOVES</span><h1>Where can it go?</h1><p>Tap to change the knight’s moves.</p></div><div class="step-edit">${board()}<div class="step-controls"><h2>What does a tap do?</h2><div class="choice chosen"><span class="radio-mark">●</span><div><strong>Move and take</strong><p>It can move to the square or take an enemy there.</p></div></div><div class="choice"><span class="radio-mark">○</span><div><strong>Slide in a line</strong><p>It stops when a piece is in the way.</p></div></div>${button('Other actions '+chevron,'text-button')}<div class="symmetry"><span class="eyebrow">APPLY EACH CHANGE</span>${button('On all sides ▾','tool')}<p>You change all matching squares.</p></div>${button('↶ Undo','text-button')}<div class="guided-worth">${value()}${button('Why?','text-button')}</div></div></div><div class="mobile-guide-tools">${tools()}<p>All matching squares change.</p></div></section></div><footer class="foot-b">${button('‹ Back','back')}<span class="guided-save">✓ Saved <span class="phone-estimate"> · About 4½ pawns · Estimate</span><span class="desktop-step-note"> on this device · You can change any step.</span><button class="text-button" tabindex="-1">Why?</button></span>${button('Try it','quiet')}${button('Next: Rules →','primary')}</footer>`;}
function appC(){return `${header('Your design')}<div class="folio"><section class="piece-card"><div class="card-border"><div class="card-top"><span class="eyebrow">CUSTOM PIECE</span><span class="serial">H</span></div><div class="card-portrait">${fig()}<div class="plinth">H</div></div><h1>Hungry Rider</h1><p class="subtitle">A knight with a second chance.</p><div class="card-worth">About 4½ pawns <span>· Estimate</span></div><div class="card-line active-line"><div><span class="eyebrow">MOVES</span><strong>Moves and takes in an L.</strong><p>It can jump over pieces.</p></div>${button('Edit '+chevron,'text-button')}</div><div class="card-line"><div><span class="eyebrow">SPECIAL · 1 OF 3</span><strong>Takes again</strong><p>${ruleText}</p></div>${button('Edit '+chevron,'text-button')}</div><div class="card-bottom"><div>${button('+ Add a rule','text-button')}${button('Look & name '+chevron,'text-button')}</div><span class="saved">✓ Saved on this device</span></div></div></section><section class="card-editor"><div class="section-heading"><div><span class="eyebrow">EDIT THE CARD</span><h2>Moves</h2></div>${button('Done','quiet')}</div><p class="editor-note">Change the board. The card updates with it.</p>${tools()}${board()}<p class="board-caption">Your changes save as you make them.</p></section></div><footer class="foot-c"><span class="foot-note">Custom pieces cannot join games yet.</span>${button('Why 4½ pawns?','text-button')}${button('Try it →','primary')}</footer>`;}
function home(){return `<header><div class="crumb">${button('‹ Back','back')}</div><h1>Workshop</h1></header><div class="home-body ${variant==='C'?'home-c':''}"><section class="start"><div>${fig()}</div><div><span class="eyebrow">START A PIECE</span><h2>${variant==='B'?'Start with one you know.':variant==='C'?'Make a piece card.':'Make your next piece.'}</h2><p>Choose a piece, then change it.</p>${button('New piece →','primary')}</div></section><div class="secondary-actions">${button('Mix two pieces','quiet')}${button('Surprise me','quiet')}</div><div class="row"><h2>Your designs</h2><span>On this device</span></div><div class="home-design">${fig()}<div><h3>Hungry Rider</h3><p>About 4½ pawns · 1 rule</p></div>${button('Open '+chevron,'text-button')}</div><p class="scope">Try and share your designs. Custom pieces cannot join games yet.</p></div>`;}
function tryScreen(){return `${header('Hungry Rider')}<div class="trial"><section><div class="section-heading"><h1>Try your piece</h1><div class="mode">${button('Edit')}${button('Try it','selected')}</div></div>${board(8,true)}<p class="trial-result">Take the pawn to try “Takes again”.</p></section><aside><span class="eyebrow">TEST BOARD</span><h2>Make a move.<br>See what happens.</h2><p>The other side does not move.</p>${rule()}<div class="row">${button('Reset','quiet')}${button('Shuffle','quiet')}</div><p class="scope">Some rules need a test setting. Protection from enemy takes cannot be tested here.</p>${value(true)}</aside></div><footer>${button('← Back to editing','primary')}<span class="foot-note">Your design stays saved.</span></footer>`;}
document.body.className = `v${variant} screen-${screen}`;
document.getElementById('app').innerHTML = screen==='home'?home():screen==='try'?tryScreen():({A:appA,B:appB,C:appC}[variant])();
// The review bar changes only the static view. All in-product controls are inert.
if(!q.has('frame')) document.body.insertAdjacentHTML('beforeend',`<nav class="review-nav" aria-label="Static design views"><b>Static mockup</b>${['A','B','C'].map(v=>`<a class="${v===variant?'current':''}" href="?variant=${v}&screen=${screen}">${v} · ${names[v]}</a>`).join('')}<span>|</span>${['home','edit','try'].map(s=>`<a class="${s===screen?'current':''}" href="?variant=${variant}&screen=${s}">${s}</a>`).join('')}</nav>`);

const panel=q.get('panel');
if(['moves','warning','share'].includes(panel)){
 let body='';
 if(panel==='moves')body=`<div class="row"><h2>Edit moves</h2>${button('Done','quiet')}</div><p>Tap a square to add or remove it.</p>${tools()}${board()}<p class="board-caption">Your changes save as you make them.</p>`;
 if(panel==='warning')body=`<div class="row"><h2>About this estimate</h2>${button('Close','quiet')}</div><span class="eyebrow">HUNGRY RIDER + DIAGONAL STEPS</span><div class="warning-number">About 7 pawns</div><p>Estimated range: 6½ to 8 pawns.</p><div class="warning-banner"><h3>Likely overpowered</h3><p>More than any pool piece but the queen.</p></div><p>It moves to more squares than any piece we measured.</p><div class="warning-fix"><p>Without the diagonal steps:<br><strong>about 4½ pawns.</strong></p>${button('Remove diagonal steps','quiet')}</div><p>This is an estimate. You can keep the piece as it is.</p>${button('Keep editing','primary')}`;
 if(panel==='share')body=`<div class="row"><h2>Your design</h2>${button('Close','quiet')}</div><p>✓ Saved on this device</p>${['Send link','Copy link','Copy as text','Make a copy','Delete design'].map(t=>button(t,'menu-item '+(t==='Delete design'?'danger':''))).join('')}<p>Custom pieces cannot join games yet.</p>`;
 document.body.insertAdjacentHTML('beforeend',`<div class="static-overlay"><section class="static-sheet">${body}</section></div>`);
}
